static _Atomic int g_ready;                                  /* published by the workers */

void *health_loop(void *arg) {
    int lfd = (int)(intptr_t)arg;                            /* socket/bind/listen, health port */
    struct pollfd p = { .fd = lfd, .events = POLLIN };
    for (;;) {
        if (poll(&p, 1, 1000) <= 0) continue;                /* re-read readiness each second */
        int c = accept(lfd, NULL, NULL), ok = atomic_load(&g_ready);
        const char *r = ok ? "HTTP/1.1 200 OK\r\n\r\nok" : "HTTP/1.1 503\r\n\r\nnot ready";
        if (write(c, r, strlen(r)) < 0) { /* prober gone */ }
        close(c);
    }
}

