#include <systemd/sd-daemon.h>

uint64_t usec = 0;
sd_watchdog_enabled(0, &usec);   /* owned/watchdog_usec from the environment */
sd_notify(0, "READY=1");        /* startup complete */
for (;;) {
    tick();                      /* one iteration of the real work loop */
    if (usec > 0) sd_notify(0, "WATCHDOG=1");
}
